WITH cleaned AS (SELECT *, ROUND(budget * 1.1, 2) AS budget_adjusted, COALESCE(location, 'OTHER') AS location_clean FROM departments WHERE dept_name IS NOT NULL AND dept_name IS DISTINCT FROM 'Legal'), base AS (SELECT *, budget / NULLIF(budget_adjusted, 0) AS budget_per_budget_adjusted FROM cleaned WHERE budget <= 2960000), metrics AS (SELECT id, dept_name, budget, budget_adjusted, location_clean, budget_per_budget_adjusted, RANK() OVER w_part AS budget_per_budget_adjusted_rank, SUM(budget_per_budget_adjusted) OVER (PARTITION BY location ORDER BY budget_per_budget_adjusted, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_budget_per_budget_adjusted, NTILE(5) OVER w_recent AS budget_adjusted_bucket, LAST_VALUE(location) IGNORE NULLS OVER (PARTITION BY dept_name ORDER BY budget_adjusted, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_location, LAG(budget_adjusted, 2) OVER (PARTITION BY dept_name ORDER BY budget, id) AS prev_budget_adjusted FROM base WINDOW w_part AS (ORDER BY budget_per_budget_adjusted NULLS LAST), w_recent AS (PARTITION BY dept_name, location ORDER BY budget_adjusted, id)), kept AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM employees x WHERE x.dept_id = s.id AND x.salary BETWEEN 83000 AND 100000)) SELECT CASE WHEN budget_adjusted_bucket >= 8 THEN 'HIGH' ELSE 'LOW' END AS budget_adjusted_bucket_tier, CASE WHEN budget_per_budget_adjusted >= 69 THEN 'HIGH' ELSE 'LOW' END AS budget_per_budget_adjusted_tier, SUM(budget_adjusted) FILTER (WHERE dept_name = 'Sales') AS sales_total_budget_adjusted, COUNT(*) AS row_count, SIZE(COLLECT_SET(dept_name)) AS num_dept_names FROM kept GROUP BY CASE WHEN budget_adjusted_bucket >= 8 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN budget_per_budget_adjusted >= 69 THEN 'HIGH' ELSE 'LOW' END ORDER BY budget_adjusted_bucket_tier DESC
